import itertools
import random

def get_max_score(pairs):
    # pairs is a list of (v1, s1, v2, s2)
    # v's are absolute values, s's are signs (1 or -1)
    vars_ = sorted(list(set([p[0] for p in pairs] + [p[2] for p in pairs])))
    var_map = {v: i for i, v in enumerate(vars_)}
    num_vars = len(vars_)

    max_s = 0
    for assignment in itertools.product([1, -1], repeat=num_vars):
        score = 0
        for v1, s1, v2, s2 in pairs:
            if assignment[var_map[v1]] == s1 or assignment[var_map[v2]] == s2:
                score += 1
        if score > max_s:
            max_s = score
    return max_s

def generate_random_pairs(M):
    pairs = []
    # To make it more challenging, we use a small number of distinct absolute values
    num_distinct_vars = random.randint(1, 2 * M)
    vars_pool = list(range(num_distinct_vars))

    # Pre-determine which signs are allowed for (k,k) and (-k,-k)
    # For each k, either only (k,k) is allowed or only (-k,-k) is allowed.
    allowed_signs = {v: random.choice([1, -1]) for v in vars_pool}

    for _ in range(M):
        v1 = random.choice(vars_pool)
        v2 = random.choice(vars_pool)
        s1 = random.choice([1, -1])
        s2 = random.choice([1, -1])

        # Constraint: if v1 == v2, then s1 must be the allowed sign for v1
        # Wait, the constraint is: at most one of (k,k) and (-k,-k) is written.
        # This means for a fixed k, we can have multiple (k,k) but no (-k,-k), or vice versa.
        if v1 == v2:
            if s1 != s2:
                # This is not a (k,k) or (-k,-k) pair, so it's always allowed
                pass
            else:
                # This is (k,k) or (-k,-k). Check if it's the allowed one.
                # Actually, we can just check if BOTH (k,k) and (-k,-k) are in the set.
                pass

        pairs.append((v1, s1, v2, s2))

    # Now, we must ensure the constraint: for each k, not both (k,k) and (-k,-k)
    # Let's just filter the pairs or regenerate them.
    # The easiest way is to just check the constraint at the end.
    return pairs

def is_valid(pairs):
    # Check if for any k, both (k,k) and (-k,-k) are present
    pairs_set = set(pairs)
    for p in pairs:
        v1, s1, v2, s2 = p
        if v1 == v2 and s1 == s2:
            # This is (k,k) or (-k,-k)
            # Check if the opposite is also present
            if (v1, -s1, v2, -s2) in pairs_set:
                return False
    return True

def solve_for_M(M, iterations=1000):
    min_max_score = M
    for _ in range(iterations):
        while True:
            pairs = generate_random_pairs(M)
            if is_valid(pairs):
                break

        score = get_max_score(pairs)
        if score < min_max_score:
            min_max_score = score
    return min_max_score

for M in range(1, 11):
    print(f"M={M}, min_max_score={solve_for_M(M)}")

